import java.nio.file.*;
public class SpoolSecureDirectoryProbe {
 public static void main(String[] args) throws Exception {
  Path path=Files.createTempDirectory("spool-directory-probe-");
  try (var stream=Files.newDirectoryStream(path)) {
   System.out.println("secureDirectory="+(stream instanceof SecureDirectoryStream<?>));
  } finally {Files.delete(path);}
 }
}
